. (Join-Path $PSScriptRoot '_Support.ps1')
$s=Read-Settings;Require-Keys $s;Assert-Baseline $s;$e=New-EvidenceFolder $s '50-secret-lifecycle';Start-EvidenceTranscript $e
try {$redis=@(docker ps --format '{{.Names}}'|Where-Object{$_ -match 'orchestrator-redis'}|Select-Object -First 1);if(-not $redis){throw 'orchestrator Redis container was not found.'};$keys=@(docker exec $redis[0] redis-cli --scan --pattern 'services_key:*');$rows=@(foreach($key in $keys){[pscustomobject]@{Key=$key;Ttl=(docker exec $redis[0] redis-cli TTL $key).Trim()}});$rows|Format-Table -AutoSize;Save-Json $rows (Join-Path $e 'service-key-ttl.json');if($rows.Count -eq 0){Write-Host 'RESULT: PASS - no workflow service keys remain.'}elseif(@($rows|Where-Object{[int]$_.Ttl -lt 0}).Count){Write-Host 'RESULT: DEFECT CONFIRMED - one or more workflow service keys have no expiry.'}else{Write-Host 'RESULT: RECORDED - workflow service keys have bounded TTLs.'}} finally {Stop-EvidenceTranscript}
